import numpy as np

def feature(item, bins, capacity):
    """For small jobs, reward bins that stay usable but get progressively tighter."""
    d = item / capacity
    r = (bins - item) / capacity
    small = (d[0] < 0.2) and (d[1] < 0.2)
    lo = np.minimum(r[:, 0], r[:, 1])
    if not small:
        return np.zeros(bins.shape[0])
    return np.where(lo > 0.0, 1.0 - lo, 0.0)

